-- ============================================================================
-- seed_etl_run_config_eci.sql  (ECI step-driver example)
--
-- Seeds COMMON.ETL_RUN_CONFIG_TBL for workflow wf_ECI_Stage_Load: one row
-- per driver row (STEP_NO = 0, IS_DRIVER = 'Y') + every transform step +
-- every publish branch.  All IS_RUN_ENABLED = 'Y' (everything runs).
-- The DELETE below removes ECI rows only, so re-running this seed is safe.
-- Run it in the COMMON schema (MDM_ETL_COMMON.COMMON).
-- NOTE: IS_DEPENDENT / DEPENDENT_ON / WORK_TABLES_PRODUCED are informational
-- for a driver run — gating is by IS_RUN_ENABLED only (see README.md).
-- ============================================================================

DELETE FROM ETL_RUN_CONFIG_TBL WHERE WORKFLOW_NAME = 'wf_ECI_Stage_Load';


-- 67 rows: 9 driver rows + 32 steps + 26 publish branches.
